public final class ContextDependentFrontierRunner {
    private static int checks;
    private interface Attempt{void run()throws Exception;}
    private static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void reject(Attempt a,String why)throws Exception{boolean no=false;try{a.run();}catch(Exception expected){no=true;}require(no,why);}
    private static Policy policy(){return new Policy(2000000,1000,1000,64000000,200000);}
    private static Mind memory()throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);return m;}
    private static Rule raw(Mind m,String text)throws Exception{return (Rule)m.compileLine(text,false,new LinkedList<ITerm>());}
    private static Member member(Mind m,int id,boolean x)throws Exception{return new Member(m,ContextProductionInventory.inspect(m,new UUID(0,id),3,x,Collections.emptyList(),1000));}
    private static Request input(Round... rounds){return new Request(policy(),10000,Arrays.asList(rounds));}
    private static Ref ref(Member m,Rule r){return new Ref(m.inventory.context,r.getId());}
    private static Step step(Member m,Rule r,Donor donor){return new Step(ref(m,r),-1,Collections.singletonList(donor));}
    private static Round round(String cut,Step... steps){return new Round(Collections.singletonMap(cut,Arrays.asList(steps)));}
    private static List<Row> produce(Mind m,int context,Rule seed,Rule... rules)throws Exception{
        List<ContextDependentProductionInspection.Step> steps=new ArrayList<>();for(Rule rule:rules)steps.add(new ContextDependentProductionInspection.Step(rule.getId(),Collections.singletonList(ContextDependentProductionInspection.Donor.original(seed.getId()))));return ContextDependentProductionInspection.inspect(m,member(m,context,true).inventory,new ContextDependentProductionInspection.Request(policy(),10000,steps)).products;
    }
    private static boolean same(Row a,Row b){return ContextDependentFrontierInspection.sameConclusion(a,b,1000000);}
    private static void alphaAndTypes()throws Exception{
        Mind m=memory();Rule seed=raw(m,"!@a @b seed(a,b);");Rule xy=raw(m,"!@a @b seed(a,b)->out(a,b);"),yx=raw(m,"!@a @b seed(a,b)->out(b,a);"),xx=raw(m,"!@a @b seed(a,b)->out(a,a);"),yy=raw(m,"!@a @b seed(a,b)->out(b,b);");List<Row> rows=produce(m,1,seed,xy,yx,xx,yy,xy);require(same(rows.get(0),rows.get(1))&&same(rows.get(1),rows.get(0)),"bijective alpha renaming permits swapping two independent variables");require(!same(rows.get(0),rows.get(2))&&!same(rows.get(2),rows.get(0)),"bijection preserves repeated-variable correlation in both directions");require(same(rows.get(2),rows.get(3)),"single repeated variable can be renamed");require(same(rows.get(0),rows.get(4))&&rows.get(0).arguments.get(0).variable!=rows.get(4).arguments.get(0).variable,"fresh result-local variable numbers are not logical identity");
        Mind values=memory();Rule h=raw(values,"!@x seed(x)->out(x);"),n=raw(values,"!seed(2);"),s=raw(values,"!seed(\"2\");");Row number=produce(values,2,n,h).get(0),text=produce(values,2,s,h).get(0);require(!same(number,text),"equal rendered scalar text cannot collapse number and string");
        Mind signs=memory();Rule ps=raw(signs,"!seed(1);"),positive=raw(signs,"!@x seed(x)->out(x);"),negative=raw(signs,"!@x ~(seed(x)&&out(x));");Row pos=produce(signs,3,ps,positive).get(0);int retained=-1,index=0;for(Domain d:negative.getTree().get(0)){if(d.getPredicate(signs).getName(signs).equals("out"))retained=index;index++;}ContextDependentProductionInspection.Result nr=ContextDependentProductionInspection.inspect(signs,member(signs,3,true).inventory,new ContextDependentProductionInspection.Request(policy(),10000,Collections.singletonList(new ContextDependentProductionInspection.Step(negative.getId(),retained,Collections.singletonList(ContextDependentProductionInspection.Donor.original(ps.getId()))))));require(!same(pos,nr.products.get(0)),"signed opposite conclusions remain different");
    }
    private static void witnesses()throws Exception{
        for(int width:new int[]{1,7,17,65}){
            Mind m=memory();StringBuilder prefix=new StringBuilder(),args=new StringBuilder(),swapped=new StringBuilder();for(int i=0;i<width;i++){prefix.append("@x").append(i).append(' ');if(i>0){args.append(',');swapped.append(',');}args.append('x').append(i);swapped.append('x').append(width>1&&i<2?1-i:i);}Rule seed=raw(m,"!"+prefix+"$u rel("+args+",u);");Rule h=raw(m,"!"+prefix+"@u rel("+args+",u)->out("+args+",u);"),permutation=width==1?h:raw(m,"!"+prefix+"@u rel("+args+",u)->out("+swapped+",u);");List<Row> rows=produce(m,100+width,seed,h,h,permutation);require(same(rows.get(0),rows.get(1)),"physical function identity and fresh alpha variables preserved across repeated materializations");if(width>1)require(!same(rows.get(0),rows.get(2)),"outer coordinate permutation cannot silently permute witness dependencies");List<Row> other=produce(m,200+width,seed,h);require(!same(rows.get(0),other.get(0)),"different physical Source headers are distinct witness identities, not asserted unequal values");for(int i=0;i<width;i++)require(rows.get(0).arguments.get(width).arguments.get(i)==rows.get(0).arguments.get(i),"compared graph preserves shared dependent coordinate "+i);reject(()->ContextDependentFrontierInspection.sameConclusion(rows.get(0),rows.get(1),1),"equality exhaustion is refusal, not false non-equivalence");
        }
    }
    private static void cyclesAndSupersets()throws Exception{
        Mind m=memory();Rule seed=raw(m,"!seed(1);"),hp=raw(m,"!@x seed(x)->p(x);"),hq=raw(m,"!@x p(x)->q(x);"),back=raw(m,"!@x q(x)->p(x);");Member x=member(m,301,true);String key=ContextDependentCutInspection.local(x.inventory.context);Round r0=round(key,step(x,hp,Donor.original(ref(x,seed))),step(x,hq,Donor.earlier(0)),step(x,back,Donor.earlier(1))),r1=round(key,step(x,hq,Donor.carried(new Ticket(0,key,2))),step(x,back,Donor.earlier(0))),r2=round(key,step(x,hq,Donor.carried(new Ticket(1,key,1))),step(x,back,Donor.earlier(0)));ContextDependentRoundInspection.Result checked=ContextDependentRoundInspection.inspect(x,Collections.emptyList(),input(r0,r1,r2));Snapshot a=ContextDependentFrontierInspection.inspect(checked.barriers.get(0),1000000,1000),b=ContextDependentFrontierInspection.inspect(checked.barriers.get(1),1000000,1000),c=ContextDependentFrontierInspection.inspect(checked.barriers.get(2),1000000,1000);require(a.common.size()==3&&b.common.size()==4&&c.common.size()==4,"new strict Source superset retained, repeated cyclic proofs canonicalized");Comparison changed=ContextDependentFrontierInspection.compare(a,b,1000000),stable=ContextDependentFrontierInspection.compare(b,c,1000000);require(changed.changed&&changed.newOrImproved>0&&changed.removedOrWorsened==0,"new superset changes frontier monotonically");require(!stable.changed&&stable.newOrImproved==0&&stable.removedOrWorsened==0,"deeper repetitions do not masquerade as new knowledge");require(c.common.stream().filter(row->row.predicate.equals("p")).count()==2,"same head with original and strict-superset Sources remains two alternatives");require(c.common.stream().anyMatch(row->row.predicate.equals("p")&&row.sources.size()==4&&row.depth==3),"minimum derivation depth retained for same conclusion and Source set");require(checked.barriers.get(2).common.size()==7&&checked.barriers.get(2).cuts.get(key).products.size()==7,"complete proof ledger remains intact after representative reduction");require(ContextDependentFrontierInspection.compare(c,a,1000000).removedOrWorsened>0,"reverse comparison detects missing evidence");reject(()->c.common.clear(),"common representatives immutable");reject(()->c.pools.clear(),"pool map immutable");reject(()->c.pools.get(key).clear(),"pool representatives immutable");reject(()->ContextDependentFrontierInspection.inspect(checked.barriers.get(2),1000000,1),"whole representative bound has no partial snapshot");reject(()->ContextDependentFrontierInspection.compare(b,c,1),"comparison work cap refuses without stable verdict");
    }
    private static void discoveryAndBasis()throws Exception{
        Mind m=memory();raw(m,"!seed(1);");raw(m,"!@x seed(x)->p(x);");Member x=member(m,401,true);Discovery first=ContextDependentRoundInspection.discoverNext(x,Collections.emptyList(),input()),second=ContextDependentRoundInspection.discoverNext(x,Collections.emptyList(),input(first.next));require(first.matchedRecipes==1&&second.matchedRecipes==1,"application count repeats");require(!ContextDependentFrontierInspection.compare(first.frontier,second.frontier,1000000).changed,"discovery exports checked detached canonical frontier");
        Mind em=memory(),am=memory(),bm=memory();Member ex=member(em,410,true),a=member(am,411,false),b=member(bm,412,false);Cut ca=new Cut("empty",Collections.singletonList(a)),cb=new Cut("empty",Collections.singletonList(b));Map<String,List<Step>> recipes=new LinkedHashMap<>();recipes.put(ContextDependentCutInspection.local(ex.inventory.context),Collections.emptyList());recipes.put(ca.key,Collections.emptyList());Snapshot ea=ContextDependentFrontierInspection.inspect(ContextDependentRoundInspection.inspect(ex,Collections.singletonList(ca),input(new Round(recipes))).barriers.get(0),10000,1000),eb=ContextDependentFrontierInspection.inspect(ContextDependentRoundInspection.inspect(ex,Collections.singletonList(cb),input(new Round(recipes))).barriers.get(0),10000,1000);require(ea.common.isEmpty()&&eb.common.isEmpty(),"empty product pools exercise hidden physical basis changes");reject(()->ContextDependentFrontierInspection.compare(ea,eb,10000),"different empty TRUST members cannot compare equal");
        Member newer=new Member(em,ContextProductionInventory.inspect(em,ex.inventory.context,4,true,Collections.emptyList(),1000));Snapshot revision=ContextDependentFrontierInspection.inspect(ContextDependentRoundInspection.inspect(newer,Collections.singletonList(ca),input(new Round(recipes))).barriers.get(0),10000,1000);reject(()->ContextDependentFrontierInspection.compare(ea,revision,10000),"revision change refuses even when row/pool content is empty");
        Mind tx=memory(),ta=memory(),tb=memory();raw(tx,"!@x seed(x)->p(x);");raw(ta,"!seed(1);");raw(tb,"!seed(1);");Member xx=member(tx,421,true),aa=member(ta,422,false),bb=member(tb,423,false);Cut trust=new Cut("both",Arrays.asList(bb,aa));Discovery d=ContextDependentRoundInspection.discoverNext(xx,Collections.singletonList(trust),input());require(d.frontier.common.size()==2,"canonical frontier retains equal heads with distinct physical Source alternatives");for(List<Row> pool:d.frontier.pools.values())require(pool.size()==2,"next-input pool receives newly exported common proofs immediately in detached frontier");Discovery reordered=ContextDependentRoundInspection.discoverNext(xx,Collections.singletonList(new Cut("both",Arrays.asList(aa,bb))),input());require(!ContextDependentFrontierInspection.compare(d.frontier,reordered.frontier,1000000).changed,"descriptor order and fresh arenas do not change frontier");
    }
    private static void stableIsNotAdmission()throws Exception{
        Mind xm=memory(),am=memory(),bm=memory();raw(xm,"!@x left(x)&&right(x)->p(x);");raw(am,"!left(1);");raw(am,"!p(1);");raw(bm,"!right(1);");raw(bm,"!~p(1);");Member x=member(xm,501,true),a=member(am,502,false),b=member(bm,503,false);List<Cut> cuts=Arrays.asList(new Cut(null,Collections.singletonList(a)),new Cut(null,Collections.singletonList(b)));Discovery first=ContextDependentRoundInspection.discoverNext(x,cuts,input()),second=ContextDependentRoundInspection.discoverNext(x,cuts,input(first.next));require(first.checked.barriers.get(0).cuts.values().stream().allMatch(c->c.finalUnitRefutations.isEmpty()),"producing round has no sibling collision yet");require(!ContextDependentFrontierInspection.compare(first.frontier,second.frontier,1000000).changed,"next-input frontier can stay equal while received qualification is newly performed");require(second.checked.barriers.get(1).cuts.values().stream().anyMatch(c->!c.finalUnitRefutations.isEmpty()),"stable frontier never certifies admission: A now refutes common negative left");
    }
    private static final class Fixture implements AutoCloseable{
        final User user=new User();final DB db=new DB();final Mind root;
        Fixture(Path d,String name)throws Exception{user.setDatabaseDir(d+File.separator);user.setUserDir(Files.createDirectories(d.resolve("operator")).toString());db.init(user);Mind m=new Mind(user);user.setCurrentMind(m);root=(Mind)m.useStorage(name);user.setCurrentMind(root);}
        @Override public void close()throws Exception{if(user.getCurrentMind().isStorageUsed())user.setCurrentMind(user.getCurrentMind().closeStorage());}
    }
    private static void owning()throws Exception{
        Path dir=Files.createTempDirectory("frontier-db-");try(Fixture f=new Fixture(dir,"X")){require(f.root.compile("!seed(1);",null,false),"actual parent seed");long revision=f.db.getRevision();Mind child=new Mind(f.root);raw(child,"!@x seed(x)->p(x);");String before=ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint;try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){Discovery first=lease.discoverDependentRound(input()),second=lease.discoverDependentRound(input(first.next));require(!ContextDependentFrontierInspection.compare(first.frontier,second.frontier,1000000).changed,"actual owning repeated application has unchanged canonical frontier");require(f.db.getRevision()==revision&&before.equals(ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"frontier capture does not write actual child/revision");raw(child,"!changed(1);");reject(()->lease.discoverDependentRound(input()),"detached snapshot never bypasses provider currentness");}finally{f.root.release(child);}}
    }
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("dependent-frontier-").toString());alphaAndTypes();witnesses();cyclesAndSupersets();discoveryAndBasis();stableIsNotAdmission();owning();System.out.println("CONTEXT_DEPENDENT_FRONTIER_PASS checks="+checks);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
